  it("splits core data shapes by measured grouping semantics and floors real vectors", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(
        'x <- floor(matrix(c(1.9, -1.1, 2.2, 3.8), 2, dimnames = list(c("r1", "r2"), c("c1", "c2"))))\nc(typeof(x), dim(x), x, unlist(dimnames(x)))',
      ),
    ).resolves.toEqual(["double", "2", "2", "1", "-2", "2", "3", "r1", "r2", "c1", "c2"]);
    await expect(runtime.eval("floor(c(a = 1.9, b = NA, c = NaN, d = Inf))")).resolves.toEqual([
      1,
      { __nativr__: "NA" },
      Number.NaN,
      Number.POSITIVE_INFINITY,
    ]);
    await expect(runtime.eval("floor(1 + 2i)")).rejects.toMatchObject({ code: "NRT3233" });
    await expect(runtime.eval("floor(factor(c('a', 'b')))")).rejects.toMatchObject({
      code: "NRT3233",
    });

    await expect(
      runtime.eval(
        'x <- split(setNames(1:6, c("a", "b", "c", "d", "e", "f")), c("b", "a", "b"))\nc(names(x), x$a, names(x$a), x$b, names(x$b))',
      ),
    ).resolves.toEqual(["a", "b", "2", "5", "b", "e", "1", "3", "4", "6", "a", "c", "d", "f"]);
    await expect(
      runtime.eval(
        'f <- factor(c("b", "a", "b", NA), levels = c("b", "unused", "a"))\nx <- split(1:4, f)\ny <- split(1:4, f, drop = TRUE)\nc(names(x), lengths(x), names(y), lengths(y))',
      ),
    ).resolves.toEqual(["b", "unused", "a", "2", "0", "1", "b", "a", "2", "1"]);

    const recycled = await runtime.evalDetailed('x <- split(1:5, c("a", "b"))\nc(x$a, x$b)');
    expect(recycled.value).toEqual([1, 3, 5, 2, 4]);
    expect(recycled.warnings).toEqual([
      { code: "NRW1014", message: "data length is not a multiple of split variable" },
    ]);
    await expect(
      runtime.eval(
        'd <- data.frame(a = 1:4, b = c("a", "b", "c", "d"))\nattr(d, "row.names") <- c("r1", "r2", "r3", "r4")\nx <- split(d, c("g", "h", "g", "h"))\nc(names(x), x$g$a, x$g$b, rownames(x$g), x$h$a, x$h$b, rownames(x$h))',
      ),
    ).resolves.toEqual(["g", "h", "1", "3", "a", "c", "r1", "r3", "2", "4", "b", "d", "r2", "r4"]);
    await expect(
      runtime.eval(
        'x <- split(1:4, list(c("a", "b", "a", "b"), c("x", "x", "y", "y")), sep = ":", lex.order = TRUE)\nc(names(x), unlist(x))',
      ),
    ).resolves.toEqual(["a:x", "a:y", "b:x", "b:y", "1", "3", "2", "4"]);
    await expect(
      runtime.eval(
        "x <- split(1:5, c(10, 2, 1, NaN, NA_real_))\nc(names(x), lengths(x), unlist(x))",
      ),
    ).resolves.toEqual(["1", "2", "10", "NaN", "1", "1", "1", "1", "3", "2", "1", "4"]);
    await expect(
      runtime.eval(`
        f <- factor(c("a", "a", "b", "b", "c", "c"), levels = c("a", "b", "c", "z"))
        atomic <- setNames(1:6, letters[1:6])
        split(atomic, f) <- list(c(10L, 20L), 30L, c(40L, 50L))
        listed <- as.list(1:6)
        split(listed, f) <- list(list("x", "y"), list("z"), list("q", "r"))
        frame <- data.frame(a = 1:4, b = letters[1:4], row.names = paste0("r", 1:4))
        groups <- factor(c("x", "x", "y", "y"))
        split(frame, groups) <- list(
          data.frame(a = c(10, 11), b = c("u", "v")),
          data.frame(a = c(20, 21), b = c("w", "z"))
        )
        \`split<-.probe\` <- function(x, f, drop = FALSE, ..., value) c("method", value)
        dispatched <- \`split<-\`(structure(1:3, class = "probe"), 1:3, value = 4)
        missing.groups <- 1:6
        split(missing.groups, factor(c("a", NA, "b", "b", "c", NA))) <- list(10L, 20L, 30L)
        empty <- NULL
        split(empty, integer()) <- list(1)
        as.character(c(
          atomic, names(atomic), unlist(listed), frame$a, frame$b, rownames(frame),
          dispatched, missing.groups, is.null(empty), typeof(\`split<-\`),
          is.primitive(\`split<-\`), names(formals(\`split<-\`))
        ))
      `),
    ).resolves.toEqual([
      "10",
      "20",
      "30",
      "30",
      "40",
      "50",
      "a",
      "b",
      "c",
      "d",
      "e",
      "f",
      "x",
      "y",
      "z",
      "z",
      "q",
      "r",
      "10",
      "11",
      "20",
      "21",
      "u",
      "v",
      "w",
      "z",
      "r1",
      "r2",
      "r3",
      "r4",
      "method",
      "4",
      "10",
      "2",
      "20",
      "20",
      "30",
      "6",
      "TRUE",
      "closure",
      "FALSE",
      "x",
      "f",
      "drop",
      "...",
      "value",
    ]);
    await expect(runtime.eval("x <- 1:3; split(x, 1:3) <- NULL")).rejects.toMatchObject({
      code: "NRT3314",
      message: "replacement has length zero",
    });
    await expect(
      runtime.eval(`
        f <- factor(c("b", "a", "b", "a"), levels = c("b", "unused", "a"))
        numeric <- unsplit(split(1:4, f), f)
        listed <- unsplit(split(as.list(letters[1:4]), f, drop = TRUE), f, drop = TRUE)
        c(numeric, unlist(listed), class(numeric), class(listed))
      `),
    ).resolves.toEqual(["1", "2", "3", "4", "a", "b", "c", "d", "integer", "list"]);
    await expect(runtime.eval("split(1:3, character())")).rejects.toMatchObject({
      code: "NRE2142",
    });
    await runtime.dispose();
  });

