    const visible = await runtime.evalDetailed("scan(text = '1 2', what = integer())");
    expect(visible.value).toEqual([1, 2]);
    expect(visible.output).toEqual([{ stream: "stdout", text: "Read 2 items\n" }]);
    await runtime.dispose();
