  it("round-trips portable serialize/saveRDS output through browser-owned binary files", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(`
        value <- list(numbers = c(a = 1L, b = NA_integer_), label = "portable")
        bytes <- serialize(value, NULL, version = 2L)
        path <- tempfile(fileext = ".rds")
        saved <- withVisible(saveRDS(value, path, version = 3L, compress = TRUE))
        restored <- readRDS(path)
        info <- infoRDS(path)
        c(
          typeof(bytes), length(bytes) > 0L,
          identical(unserialize(bytes), value),
          is.null(saved$value), saved$visible,
          identical(restored, value), info$version, info$format,
          unlink(path)
        )
      `),
    ).resolves.toEqual(["raw", "TRUE", "TRUE", "TRUE", "FALSE", "TRUE", "3", "xdr", "0"]);
    await runtime.dispose();
  });

  it("round-trips ordinary environments with shared and self references", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(`
        source <- new.env(parent = emptyenv(), hash = FALSE)
        source$value <- 7L
        source$self <- source
        attr(source, "label") <- "owned"
        restored <- unserialize(serialize(list(left = source, right = source), NULL))
        c(
          restored$left$value,
          identical(restored$left, restored$right),
          identical(restored$left$self, restored$left),
          identical(parent.env(restored$left), emptyenv()),
          attr(restored$left, "label")
        )
      `),
    ).resolves.toEqual(["7", "TRUE", "TRUE", "TRUE", "owned"]);
    await runtime.dispose();
  });

