  it("retains compound formula language for package-authored formula-to-function adapters", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(`
        f <- x + value ~ { y <- x + value; if (y > 0) y else -y }
        c(typeof(f), class(f), length(f), all.vars(f), deparse(f[[2]]))
      `),
    ).resolves.toEqual(["language", "formula", "3", "x", "value", "y", "x + value"]);
    await expect(
      runtime.eval(`
        as.function.formula <- function(x) {
          vars <- all.vars(x[[2]])
          f <- function() NULL
          formals(f) <- rep(alist(value = ), length(vars))
          names(formals(f)) <- vars
          body(f) <- x[[length(x)]]
          environment(f) <- environment(x)
          f
        }
        converted <- as.function.formula(x + value ~ {
          total <- x + value
          if (total > 0) total else -total
        })
        c(converted(2, 3), converted(-5, 2), names(formals(converted)))
      `),
    ).resolves.toEqual(["5", "3", "x", "value"]);
    await runtime.dispose();
  });

  it("splits arbitrary arrays over ordered numeric, negative, and named margins", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(`
        x <- array(
          1:24,
          c(2, 3, 4),
          dimnames = list(
            row = c("r1", "r2"),
            col = c("c1", "c2", "c3"),
            plane = paste0("z", 1:4)
          )
        )
        by_col <- asplit(x, "col")
        reordered <- asplit(x, c(3, 1))
        negative <- asplit(x, -2)
        dropped <- asplit(x, 2, drop = TRUE)
        zero <- asplit(
          array(integer(), c(0, 2), dimnames = list(character(), c("a", "b"))),
          2
        )
        listed <- asplit(
          array(list(1L, "a", NULL, TRUE), c(2, 2),
                dimnames = list(r = c("r1", "r2"), c = c("c1", "c2"))),
          2
        )
        list(
          by_col[[2]], dim(by_col[[2]]), unlist(dimnames(by_col[[2]])),
          dim(by_col), unlist(dimnames(by_col)), names(dimnames(by_col)),
          reordered[[2]], dim(reordered), names(dimnames(reordered)),
          negative[[1]], dim(negative),
          is.null(dim(dropped[[1]])), is.null(attributes(dropped[[1]])),
          dim(zero), dim(zero[[1]]), length(zero[[1]]),
          listed[[1]][[1]], listed[[1]][[2]], dim(listed[[1]]),
          names(formals(asplit))
        )
      `),
    ).resolves.toEqual([
      [3, 4, 9, 10, 15, 16, 21, 22],
      [2, 4],
      ["r1", "r2", "z1", "z2", "z3", "z4"],
      3,
      ["c1", "c2", "c3"],
      "col",
      [7, 9, 11],
      [4, 2],
      ["plane", "row"],
      [1, 3, 5],
      [2, 4],
      true,
      true,
      2,
      0,
      0,
      1,
      "a",
      2,
      ["x", "MARGIN", "drop"],
    ]);
    await expect(runtime.eval("asplit(1:3, 1)")).rejects.toMatchObject({ code: "NRT3467" });
    await expect(runtime.eval("asplit(array(1:4, c(2, 2)), c(1, 2))")).rejects.toMatchObject({
      code: "NRT3467",
    });
    await expect(runtime.eval("asplit(array(1:4, c(2, 2)), 'row')")).rejects.toMatchObject({
      code: "NRT3467",
    });
    await runtime.dispose();
  });

  it("coerces storage modes while preserving ordinary attributes", async () => {
    const runtime = await session();
    await expect(
      runtime.eval(`
        x <- structure(c("1", "2"), names = c("a", "b"), marker = "kept")
        storage.mode(x) <- "integer"
        y <- structure(list(1L, "2"), names = c("left", "right"), marker = "list")
        storage.mode(y) <- "double"
        z <- structure(c("a", "b"), names = c("first", "second"), marker = "cells")
        storage.mode(z) <- "list"
        list(
          x, storage.mode(x), names(x), attr(x, "marker"),
          y, storage.mode(y), names(y), attr(y, "marker"),
          unlist(z), storage.mode(z), names(z), attr(z, "marker"),
          storage.mode(NULL), storage.mode(function() NULL), storage.mode(quote(x + 1))
        )
      `),
    ).resolves.toEqual([
      [1, 2],
      "integer",
      ["a", "b"],
      "kept",
      [1, 2],
      "double",
      ["left", "right"],
      "list",
      ["a", "b"],
      "list",
      ["first", "second"],
      "cells",
      "NULL",
      "function",
      "language",
    ]);
    await expect(
      runtime.evalDetailed('x <- c("1", "bad"); storage.mode(x) <- "integer"; x'),
    ).resolves.toMatchObject({
      value: [1, NA],
      warnings: [{ code: "NRW1006", message: "NAs introduced by coercion" }],
    });
    await expect(runtime.eval('x <- 1; storage.mode(x) <- "single"')).rejects.toMatchObject({
      code: "NRE2258",
    });
    await runtime.dispose();
  });

  it("applies zoo's usage-ranked ragged-array grouping path", async () => {
    const runtime = await session();
    await runtime.eval(`
      x <- 1:6
      screens <- factor(c(1, 1, 2, 2, 3, 3))
      f <- function(idx) range(idx)
      ranges <- tapply(x, screens, f)
    `);
    await expect(runtime.eval("unlist(ranges)")).resolves.toEqual([1, 2, 3, 4, 5, 6]);
    await expect(runtime.eval("c(dim(ranges), unlist(dimnames(ranges)))")).resolves.toEqual([
      "3",
      "1",
      "2",
      "3",
    ]);

    await expect(
      runtime.eval(`
        a <- factor(c("a", "a", "b", "b", "a", "a", "b", "b"), levels = c("a", "b"))
        b <- factor(c("x", "y", "x", "y", "x", "y", "x", "y"), levels = c("x", "y", "z"))
        grouped <- tapply(1:8, list(row = a, col = b), sum)
        c(grouped, dim(grouped), unlist(dimnames(grouped)), names(dimnames(grouped)))
      `),
    ).resolves.toEqual([
      "6",
      "10",
      "8",
      "12",
      NA,
      NA,
      "2",
      "3",
      "a",
      "b",
      "x",
      "y",
      "z",
      "row",
      "col",
    ]);
    await expect(
      runtime.eval(`
        g <- factor(c("b", "a", "b", "a"), levels = c("a", "b", "c"))
        c(tapply(1:4, g, mean, default = "x"),
          unlist(tapply(1:4, g, range, simplify = FALSE)),
          is.null(tapply(1:4, g, range, simplify = FALSE)[[3]]))
      `),
    ).resolves.toEqual(["3", "2", "x", "2", "4", "1", "3", "TRUE"]);
    await expect(
      runtime.eval(`
        ids <- tapply(1:5, factor(c("b", "a", NA, "b", "c"),
          levels = c("a", "b", "c", "d")), FUN = NULL)
        means <- tapply(c(1, NA, 3, 4), c("a", "a", "b", "b"), "mean", na.rm = TRUE)
        c(ids, means)
      `),
    ).resolves.toEqual([2, 1, NA, 2, 3, 1, 3.5]);
    await expect(runtime.eval("tapply(1:3, c('a', 'b'), sum)")).rejects.toMatchObject({
      code: "NRE2144",
    });
    await expect(runtime.eval("tapply(integer(), list(), sum)")).rejects.toMatchObject({
      code: "NRE2143",
    });
    await expect(
      runtime.eval("tapply(1:2, factor(c('a', 'b')), sum, default = 8:9)"),
    ).rejects.toMatchObject({ code: "NRT3338" });
    await runtime.dispose();

    const limited = await createR({
      execution: "inline",
      assets,
      limits: { maxVectorLength: 32 },
    });
    await expect(
      limited.eval("tapply(1, list(factor(1, levels = 1:8), factor(1, levels = 1:8)), sum)"),
    ).rejects.toMatchObject({ code: "NRL4002" });
    await limited.dispose();
  });

