    await expect(runtime.eval("as.character(quote(f(g(x)))[[c(2, 1)]])")).resolves.toBe("g");
    await expect(runtime.eval('eval(as.call(list(as.name("+"), 1, 2)))')).resolves.toBe(3);
    await expect(runtime.eval("typeof(`+`)")).resolves.toBe("builtin");
